"""Read-only frozen MeSH ranking: current distance tiers, descriptor count, descriptor IDF.
Topic sets contain ALL actual mappings minus check tags; only explicit major-topic Article edges.
"""
import csv,hashlib,subprocess,sys
from common import *
import common
D=C
POPULATION=os.environ.get("ARTICLE_POPULATION","with_stubs")
assert POPULATION in ["with_stubs","without_stubs"]
R=P/"results"/POPULATION;R.mkdir(exist_ok=True);T=P/"tables"/POPULATION;T.mkdir(exist_ok=True);common.R=R
def filter_population(con):
 if POPULATION=="without_stubs":
  con.execute("CREATE TEMP TABLE am AS SELECT m.* FROM am m JOIN article a ON a.id=m.article WHERE NOT a.stub")
  con.execute("CREATE TEMP TABLE article AS SELECT * FROM article WHERE NOT stub")
  con.execute("CREATE TEMP TABLE nodes AS SELECT * FROM nodes WHERE NOT stub")
  con.execute("CREATE TEMP TABLE incoming AS SELECT cc.object article,count(DISTINCT cc.subject) in_corpus_citations FROM base.c cc JOIN article a ON a.id=cc.subject JOIN article b ON b.id=cc.object WHERE cc.subject<>cc.object GROUP BY cc.object")
ORDER={'current':'direct_matches DESC,one_matches DESC,deeper_matches DESC,in_corpus_citations DESC,article','count':'direct_matches DESC,narrow_matches DESC,in_corpus_citations DESC,article','idf':'direct_idf DESC,narrow_idf DESC,in_corpus_citations DESC,article'}
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  while b:=f.read(8*1024*1024):h.update(b)
 return h.hexdigest()
def main():
 con=duckdb.connect(str(D/'analysis.duckdb'),read_only=True);con.execute("SET threads=4;SET memory_limit='8GB'");con.execute('ATTACH ? AS base (READ_ONLY)',[str(C/'independent_audit/audit.duckdb')]);filter_population(con);reg=Registry(con,'ranking_variants');prep=[]
 def create(sql,params=None):
  con.execute(sql,params or []);prep.append(dict(sql=sql,parameters=params or []));dump(R/'ranking_variants_preparation_queries.json',prep)
 create("CREATE TEMP TABLE eligible AS SELECT DISTINCT article,descriptor FROM am WHERE edge_major IS TRUE AND NOT check_tag AND NOT EXISTS(SELECT 1 FROM stop WHERE id=descriptor)")
 create("CREATE TEMP TABLE qterms AS SELECT DISTINCT s.key seed,t.object query_descriptor FROM seeds s JOIN tm t ON t.subject=s.id WHERE s.kind='topic' AND NOT EXISTS(SELECT 1 FROM stop WHERE id=t.object) UNION SELECT DISTINCT s.key,a.descriptor FROM seeds s JOIN am a ON a.article=s.id WHERE s.kind='article' AND a.edge_major IS TRUE AND NOT a.check_tag AND NOT EXISTS(SELECT 1 FROM stop WHERE id=a.descriptor)")
 reg.run('query_sets',"SELECT s.key seed,s.id seed_id,s.kind,s.area,q.query_descriptor,n.name FROM seeds s JOIN qterms q ON q.seed=s.key JOIN nodes n ON n.id=q.query_descriptor ORDER BY 1,5",'All MedlinePlus topic mappings; all major-topic Article query descriptors, check tags excluded, no single-term reduction.')
 # All six query sets must remain identical to the preceding downward comparison.
 assert con.execute('SELECT count(*) FROM ((SELECT seed,query_descriptor FROM qterms EXCEPT SELECT seed,query_descriptor FROM query_terms) UNION ALL (SELECT seed,query_descriptor FROM query_terms EXCEPT SELECT seed,query_descriptor FROM qterms))').fetchone()[0]==0
 create("CREATE TEMP TABLE idf AS SELECT descriptor,count(DISTINCT article) df,ln(((SELECT count(DISTINCT article) FROM eligible)+1.0)/(count(DISTINCT article)+1.0))+1.0 idf FROM eligible GROUP BY descriptor")
 reg.run('idf_denominator',"SELECT (SELECT count(DISTINCT article) FROM eligible) documents,(SELECT count(*) FROM eligible) distinct_article_descriptor_pairs,(SELECT count(*) FROM idf) descriptors",'N is distinct Articles with at least one eligible non-check major-topic edge; df(t) is distinct Articles carrying t as an eligible major topic; idf=1+ln((N+1)/(df+1)). No hierarchy aggregation in df.')
 create("CREATE TEMP TABLE expansion AS WITH raw AS (SELECT q.*,m.mode,q.query_descriptor matched_descriptor,0 distance,NULL::VARCHAR hierarchy_edge,-1 priority FROM qterms q CROSS JOIN modes m UNION ALL SELECT q.*,m.mode,h.child,h.depth,h.edge_id,h.priority FROM qterms q JOIN hierarchy h ON h.parent=q.query_descriptor CROSS JOIN modes m WHERE (m.level=2 OR (m.level=1 AND h.priority=0))) SELECT * EXCLUDE(priority) FROM raw WHERE NOT EXISTS(SELECT 1 FROM stop WHERE id=matched_descriptor) QUALIFY row_number() OVER(PARTITION BY seed,mode,query_descriptor,matched_descriptor ORDER BY distance,priority,hierarchy_edge)=1")
 create("CREATE TEMP TABLE neighbors AS SELECT s.key seed,c.object article FROM seeds s JOIN base.c c ON c.subject=s.id WHERE s.kind='article' UNION SELECT s.key,c.subject FROM seeds s JOIN base.c c ON c.object=s.id WHERE s.kind='article'")
 create("CREATE TEMP TABLE hits AS SELECT e.*,a.article,d.df,d.idf FROM expansion e JOIN eligible a ON a.descriptor=e.matched_descriptor JOIN idf d ON d.descriptor=e.matched_descriptor JOIN seeds s ON s.key=e.seed WHERE s.kind='topic' OR (a.article<>s.id AND EXISTS(SELECT 1 FROM neighbors n WHERE n.seed=e.seed AND n.article=a.article))")
 # One credit per ORIGINAL query descriptor. Direct always wins; IDF uses the most informative actual
 # narrower descriptor for that query when no direct match exists, rather than summing many child tags.
 create("CREATE TEMP TABLE closest AS SELECT * FROM hits QUALIFY row_number() OVER(PARTITION BY seed,mode,article,query_descriptor ORDER BY distance,matched_descriptor)=1")
 create("CREATE TEMP TABLE idf_choice AS SELECT * FROM hits QUALIFY row_number() OVER(PARTITION BY seed,mode,article,query_descriptor ORDER BY (distance=0) DESC,idf DESC,distance,matched_descriptor)=1")
 create("CREATE TEMP TABLE idf_scores AS SELECT seed,mode,article,sum(idf) FILTER(WHERE distance=0) direct_idf,sum(idf) FILTER(WHERE distance>0) narrow_idf FROM idf_choice GROUP BY 1,2,3")
 # 12 decimal places stabilize floating-point SQL/Python ordering across engines; no fitted parameters.
 create("CREATE TEMP TABLE scores AS SELECT c.seed,c.mode,c.article,count(*) FILTER(WHERE distance=0) direct_matches,count(*) FILTER(WHERE distance=1) one_matches,count(*) FILTER(WHERE distance>1) deeper_matches,count(*) FILTER(WHERE distance>0) narrow_matches,round(coalesce(d.direct_idf,0),12) direct_idf,round(coalesce(d.narrow_idf,0),12) narrow_idf,coalesce(i.in_corpus_citations,0) in_corpus_citations FROM closest c JOIN idf_scores d USING(seed,mode,article) LEFT JOIN incoming i ON i.article=c.article GROUP BY c.seed,c.mode,c.article,d.direct_idf,d.narrow_idf,i.in_corpus_citations")
 create("CREATE TEMP TABLE branches AS SELECT DISTINCT e.seed,e.mode,e.query_descriptor,e.matched_descriptor,b.child branch FROM expansion e JOIN hierarchy b ON b.parent=e.query_descriptor AND b.priority=0 WHERE e.distance>0 AND NOT EXISTS(SELECT 1 FROM stop WHERE id=b.child) AND (e.matched_descriptor=b.child OR EXISTS(SELECT 1 FROM hierarchy z WHERE z.child=e.matched_descriptor AND z.parent=b.child))")
 # Subtrees are defined by immediate CHILD branches of each original query descriptor. An Article
 # reached via several branches under polyhierarchy is not uniquely attributable to a single subtree.
 create("CREATE TEMP TABLE branch_hits AS SELECT DISTINCT h.seed,h.mode,h.article,h.query_descriptor,b.branch FROM hits h JOIN branches b USING(seed,mode,query_descriptor,matched_descriptor) WHERE h.distance>0")
 create("CREATE TEMP TABLE attribution AS WITH stats AS (SELECT s.seed,s.mode,s.article,count(DISTINCT h.query_descriptor||' > '||b.branch) branches,count(DISTINCT h.query_descriptor||' > '||h.matched_descriptor) FILTER(WHERE h.distance>0 AND b.branch IS NULL) unresolved FROM scores s JOIN hits h USING(seed,mode,article) LEFT JOIN branches b USING(seed,mode,query_descriptor,matched_descriptor) GROUP BY 1,2,3) SELECT s.*,t.branches,t.unresolved,(s.direct_matches=0 AND t.branches=1 AND t.unresolved=0) single_subtree_only FROM scores s JOIN stats t USING(seed,mode,article)")
 create('CREATE TEMP TABLE rankings AS '+ ' UNION ALL '.join(f"SELECT *, '{v}' variant,row_number() OVER(PARTITION BY seed,mode ORDER BY {o}) rank FROM scores" for v,o in ORDER.items()))
 reg.run('candidate_counts',"SELECT seed,mode,count(*) candidates,count(*) FILTER(WHERE direct_matches>0) direct_candidates,count(*) FILTER(WHERE single_subtree_only) single_subtree_only_candidates,count(*) FILTER(WHERE direct_matches=0 AND unresolved>0) unresolved_hierarchy_only_candidates FROM attribution GROUP BY 1,2 ORDER BY 1,2",'Same candidates for all scoring variants; score changes only order, none/one/full downward expansion unchanged.')
 reg.run('idf_terms',"SELECT DISTINCT e.seed,e.mode,e.query_descriptor,e.matched_descriptor,n.name,d.df,d.idf FROM expansion e LEFT JOIN idf d ON d.descriptor=e.matched_descriptor JOIN nodes n ON n.id=e.matched_descriptor ORDER BY 1,2,3,4",'Corpus IDF for every query/expanded descriptor, including NULL for zero eligible documents (cannot match an Article).')
 reg.run('top100',"SELECT r.*,a.single_subtree_only,a.branches,a.unresolved FROM rankings r JOIN attribution a USING(seed,mode,article) WHERE rank<=100 ORDER BY seed,mode,variant,rank",'Exact top 100 or complete short list for every one of six queries, three modes, three scoring rules. Actual list length is the denominator.')
 reg.run('guideline_review_first',"SELECT r.*,a.pub_types,a.publication_priority FROM rankings r JOIN article a ON a.id=r.article WHERE starts_with(seed,'topic') AND a.gr QUALIFY row_number() OVER(PARTITION BY seed,mode,variant ORDER BY a.publication_priority,r.rank)<=20 ORDER BY seed,mode,variant,a.publication_priority,r.rank",'Separate guideline/review-first browsing view; core ranking tests remain the declared MeSH scores.')
 create("CREATE TEMP TABLE tops AS SELECT r.*,k.k FROM rankings r CROSS JOIN (VALUES (20),(100)) k(k) WHERE r.rank<=k.k")
 reg.run('expansion_counts',"SELECT seed,mode,count(DISTINCT query_descriptor) query_descriptors,count(DISTINCT matched_descriptor) expanded_descriptors,count(*) descriptor_map_rows FROM expansion GROUP BY 1,2 ORDER BY 1,2",'Actual vocabulary fan-out, including exported descriptors without any eligible Article; no fabricated closure.')
 reg.run('candidate_mode_overlap',"SELECT a.seed,a.mode mode_a,b.mode mode_b,count(*) intersection,(SELECT count(*) FROM scores s WHERE s.seed=a.seed AND s.mode=a.mode) count_a,(SELECT count(*) FROM scores s WHERE s.seed=a.seed AND s.mode=b.mode) count_b FROM scores a JOIN scores b ON a.seed=b.seed AND a.article=b.article AND a.mode<b.mode GROUP BY 1,2,3 ORDER BY 1,2,3",'Exact candidate intersections across expansion modes, same query and Article population.')
 reg.run('toplist_mode_overlap',"SELECT a.seed,a.variant,a.k,a.mode mode_a,b.mode mode_b,count(*) intersection,(SELECT count(*) FROM tops t WHERE t.seed=a.seed AND t.variant=a.variant AND t.mode=a.mode AND t.k=a.k) count_a,(SELECT count(*) FROM tops t WHERE t.seed=a.seed AND t.variant=a.variant AND t.mode=b.mode AND t.k=a.k) count_b FROM tops a JOIN tops b ON a.seed=b.seed AND a.article=b.article AND a.variant=b.variant AND a.k=b.k AND a.mode<b.mode GROUP BY 1,2,3,4,5 ORDER BY 1,2,3,4,5",'Top-20/top-100 intersections across expansion modes; actual list lengths retained.')
 reg.run('list_metrics',"SELECT t.seed,t.mode,t.variant,t.k,count(*) list_size,count(*) FILTER(WHERE a.single_subtree_only) single_subtree_only_count,count(*) FILTER(WHERE a.single_subtree_only)*1.0/count(*) single_subtree_only_share,count(*) FILTER(WHERE a.direct_matches=0) hierarchy_only_count,count(*) FILTER(WHERE a.direct_matches=0 AND a.branches>1) multi_branch_hierarchy_only_count,count(*) FILTER(WHERE a.direct_matches=0 AND a.unresolved>0) unresolved_hierarchy_only_count FROM tops t JOIN attribution a USING(seed,mode,article) GROUP BY 1,2,3,4 ORDER BY 1,2,3,4",'Share reached only through one unambiguous narrower immediate-child subtree; no direct matches anywhere in the query set. Denominator min(k,candidate_count), not k for short lists.')
 reg.run('top20_overlap',"SELECT a.seed,a.mode,a.variant,count(*) intersection,(SELECT count(*) FROM rankings r WHERE r.seed=a.seed AND r.mode=a.mode AND r.variant=a.variant AND rank<=20) variant_size,(SELECT count(*) FROM rankings r WHERE r.seed=a.seed AND r.mode=a.mode AND r.variant='current' AND rank<=20) current_size FROM rankings a JOIN rankings b ON a.seed=b.seed AND a.mode=b.mode AND a.article=b.article WHERE a.variant<>'current' AND b.variant='current' AND a.rank<=20 AND b.rank<=20 GROUP BY 1,2,3 ORDER BY 1,2,3",'Top-20 set overlap versus current strict-major downward distance-tier ranking. Short-list denominators retained; Jaccard uses intersection/(variant_size+current_size-intersection).')
 reg.run('branch_hubs',"SELECT t.seed,t.mode,t.variant,t.k,b.query_descriptor,b.branch,n.name,count(DISTINCT t.article) top_list_incidence,count(DISTINCT t.article) FILTER(WHERE a.direct_matches=0) hierarchy_only_incidence,(SELECT count(*) FROM tops z WHERE z.seed=t.seed AND z.mode=t.mode AND z.variant=t.variant AND z.k=t.k) list_size FROM tops t JOIN branch_hits b USING(seed,mode,article) JOIN attribution a USING(seed,mode,article) JOIN nodes n ON n.id=b.branch GROUP BY 1,2,3,4,5,6,7 QUALIFY row_number() OVER(PARTITION BY t.seed,t.mode,t.variant,t.k ORDER BY top_list_incidence DESC,b.query_descriptor,b.branch)<=5 ORDER BY seed,mode,variant,k,top_list_incidence DESC,query_descriptor,branch",'Hub concentration = largest immediate-child branch incidence / actual top-list length. Counts ANY eligible narrower-term support including Articles also matching a query directly. Multiple branches can overlap; no summing. Missing rows mean zero narrower-branch incidence.')
 reg.run('descriptor_hubs',"SELECT t.seed,t.mode,t.variant,t.k,h.matched_descriptor,n.name,count(DISTINCT t.article) top_list_incidence,(SELECT count(*) FROM tops z WHERE z.seed=t.seed AND z.mode=t.mode AND z.variant=t.variant AND z.k=t.k) list_size FROM tops t JOIN hits h USING(seed,mode,article) JOIN nodes n ON n.id=h.matched_descriptor WHERE NOT EXISTS(SELECT 1 FROM qterms q WHERE q.seed=t.seed AND q.query_descriptor=h.matched_descriptor) GROUP BY 1,2,3,4,5,6 QUALIFY row_number() OVER(PARTITION BY t.seed,t.mode,t.variant,t.k ORDER BY top_list_incidence DESC,h.matched_descriptor)<=5 ORDER BY seed,mode,variant,k,top_list_incidence DESC,matched_descriptor",'Secondary descriptor hub diagnostic: most frequent expanded non-query descriptor / actual list size. Uses raw eligible support, not just a scoring-selected descriptor.')
 reg.run('credit_audit',"SELECT c.*,n.name matched_name FROM idf_choice c JOIN nodes n ON n.id=c.matched_descriptor JOIN rankings r USING(seed,mode,article) WHERE r.variant='idf' AND r.rank<=100 ORDER BY c.seed,c.mode,r.rank,c.query_descriptor",'Actual descriptor/df/IDF selected for each credited original query descriptor in IDF top 100; one credit maximum per original descriptor.')
 reg.run('subtree_audit',"SELECT DISTINCT b.*,n.name branch_name FROM branch_hits b JOIN rankings r USING(seed,mode,article) JOIN nodes n ON n.id=b.branch WHERE r.rank<=100 ORDER BY b.seed,b.mode,b.article,b.query_descriptor,b.branch",'Branch membership witnesses for union of all variants top 100. Branch paths use actual exported immediate-child and ancestor rows; unresolved membership is reported separately.')
 for name,rows in reg.results.items():
  if not rows:continue
  with (T/('ranking_variants_'+name+'.csv')).open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 con.close()
 dump(R/'execution.json',dict(population=POPULATION,code_commit=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),invocation=sys.argv,source_manifest_sha256=json.loads((P/'results/input_verification.json').read_text())['manifest_sha256']));print('scoring variants complete',flush=True)
if __name__=='__main__':main()
